t.script:

(function () {
    function align() {
        var page = document.querySelector('.bunna-ann-container');
        var brand = document.querySelector('header .navbar-brand');
        if (!page || !brand) { return; }
        var vw = document.documentElement.clientWidth;
        var left = brand.getBoundingClientRect().left;
        var right = null;
        var cta = document.querySelector('header .btn_cta');
        if (cta && cta.getBoundingClientRect().width > 0) {
            right = cta.getBoundingClientRect().right;
        } else {
            var box = brand.closest('.container, .container-fluid');
            if (box) {
                right = box.getBoundingClientRect().right
                    - parseFloat(window.getComputedStyle(box).paddingRight || '0');
            }
        }
        if (left >= 0 && left < vw / 2) {
            page.style.setProperty('--bunna-ann-left', left + 'px');
        }
        if (right !== null && right > vw / 2 && right <= vw) {
            page.style.setProperty('--bunna-ann-right', (vw - right) + 'px');
        }
    }
    var pending = false;
    function schedule() {
        if (pending) { return; }
        pending = true;
        window.requestAnimationFrame(function () { pending = false; align(); });
    }
    align();
    window.addEventListener('load', align);
    window.addEventListener('resize', schedule);
})();


(function () {
    function init() {
        var list = document.querySelector('.bunna-ann-list');
        if (!list) { return; }
        list.addEventListener('click', function (event) {
            var card = event.target.closest('.bunna-ann-card');
            if (!card) { return; }
            // links and buttons keep their own behaviour
            if (event.target.closest('a, button, input, select, textarea, label')) { return; }
            // someone selecting text to copy it should not be sent away
            var selection = window.getSelection ? window.getSelection().toString() : '';
            if (selection) { return; }
            var href = card.getAttribute('data-href');
            if (href) { window.location.href = href; }
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();


(function () {
    function init() {
        var modal = document.getElementById('annViewer');
        if (!modal) { return; }
        var frame = modal.querySelector('iframe');
        var img = modal.querySelector('img');
        var title = modal.querySelector('.modal-title');
        modal.addEventListener('show.bs.modal', function (e) {
            var btn = e.relatedTarget;
            if (!btn) { return; }
            title.textContent = btn.getAttribute('data-title') || '';
            var src = btn.getAttribute('data-src');
            if (btn.getAttribute('data-kind') === 'image') {
                frame.style.display = 'none';
                frame.removeAttribute('src');
                img.src = src;
                img.style.display = 'block';
            } else {
                img.style.display = 'none';
                img.removeAttribute('src');
                frame.src = src;
                frame.style.display = 'block';
            }
        });
        modal.addEventListener('hidden.bs.modal', function () {
            frame.removeAttribute('src');
            img.removeAttribute('src');
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();


(function () {
    function init() {
        var modal = document.getElementById('annPhotoViewer');
        if (!modal) { return; }
        var buttons = Array.prototype.slice.call(document.querySelectorAll('.bunna-ann-thumbbtn'));
        var img = document.getElementById('annPhotoFull');
        var caption = document.getElementById('annPhotoCaption');
        var counter = document.getElementById('annPhotoCounter');
        var current = 0;
        function show(index) {
            if (index < 0) { index = buttons.length - 1; }
            if (index >= buttons.length) { index = 0; }
            current = index;
            img.src = buttons[index].getAttribute('data-full');
            caption.textContent = buttons[index].getAttribute('data-caption') || '';
            counter.textContent = (index + 1) + ' / ' + buttons.length;
            var next = buttons[(index + 1) % buttons.length];
            new Image().src = next.getAttribute('data-full');
        }
        buttons.forEach(function (button, index) {
            button.addEventListener('click', function () { show(index); });
        });
        modal.querySelector('.prev').addEventListener('click', function () { show(current - 1); });
        modal.querySelector('.next').addEventListener('click', function () { show(current + 1); });
        document.addEventListener('keydown', function (event) {
            if (!modal.classList.contains('show')) { return; }
            if (event.key === 'ArrowLeft') { show(current - 1); }
            if (event.key === 'ArrowRight') { show(current + 1); }
        });
        modal.addEventListener('hidden.bs.modal', function () { img.removeAttribute('src'); });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
